/**
 * Test flow for Monthly trigger
 * Tests: Monthly scheduled trigger with day of month and time configuration
 */

import { action, Flow, wfa, trigger } from '@servicenow/sdk/automation'

export const testMonthlyTrigger = Flow(
    {
        $id: Now.ID['test_monthly_trigger_flow'],
        name: 'Test Monthly Trigger',
        description: 'Tests the Monthly trigger running on specified day of month',
    },
    wfa.trigger(
        trigger.scheduled.monthly,
        { $id: Now.ID['test_monthly_trigger'] },
        {
            day_of_month: 1,
            time: Time(
                {
                    hours: 11,
                    minutes: 11,
                    seconds: 11,
                },
                'UTC'
            ),
        }
    ),
    (_params) => {
        // Log trigger outputs
        wfa.action(
            action.core.log,
            { $id: Now.ID['test_monthly_trigger_log'] },
            {
                log_level: 'info',
                log_message: `Monthly Trigger - Run Start Time: ${wfa.dataPill(_params.trigger.run_start_time, 'glide_date_time')}, Run Start Date/Time: ${wfa.dataPill(_params.trigger.run_start_date_time, 'glide_date_time')}`,
            }
        )
    }
)
